import{_ as n,l,o as e,c as o,v as t,p as i,x as r,d as B,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"TLB","description":"","frontmatter":{"title":"TLB","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tlb-translate.md","filePath":"cs/tlb-translate.md","lastUpdated":1789023840000}'),A={name:"cs/tlb-translate.md"};function p(h,a,T,E,P,L){const s=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="tlb" tabindex="-1">TLB <a class="header-anchor" href="#tlb" aria-label="Permalink to &quot;TLB&quot;">​</a></h1><div class="epigraph"><p>页表在 DRAM 里，每次 load 先查表再访存会把 CPI 毁掉；把最近的 VPN→PPN 放进 SRAM 相联阵列，翻译才跟得上流水线。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/paging-vm">上一课</a>让每条访存先走页表。页表本身是 DRAM 中的数组，一次翻译至少再付一次访存，缺失时更多。<a href="/cs/paging-vm">局部性原理</a>对 VPN 同样成立：近期用的页还会再用。<a href="/cs/direct-mapped-cache">直接映射 Cache</a>已经演示过标签阵列。本课不重讲页表项里的权限位。缺口是：翻译必须有自己的小 cache。本课只交出 TLB。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>五级 MEM 级一拍要完成「虚拟地址 → 物理地址 → cache」。若每拍走 DRAM 页表，翻译延迟与缺页同量级，流水线退回多周期。缺口不是取消分页，而是<strong>用相联 SRAM 记住少量最近翻译</strong>，命中则一拍给出 PPN。</p><p>TLB 缺失不是缺页：页可能在 DRAM，只是翻译没在 TLB 里。硬件或软件再去走页表，填 TLB。缺页仍按上一课的精确异常走。</p><p><span class="marginnote">TLB 是翻译旁视缓冲，不是数据 cache。它存的是页表项的副本，粒度是页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>TLB 条目：VPN 标签（或标签+索引）、PPN、有效、权限、有时 ASID。全相联或小规模组相联，因为条目少。访存时并行查 TLB 与（若用虚拟索引）cache；TLB 命中则用 PPN 完成物理标签比较。</p>',9)),(e(),i(d,null,{default:r(()=>[c(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA%5B%22%E8%99%9A%E6%8B%9F%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20TLB%5B%22TLB%22%5D%0A%20%20TLB%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20PPN%5B%22PPN%20%E2%86%92%20%E7%89%A9%E7%90%86%E5%9C%B0%E5%9D%80%22%5D%0A%20%20TLB%20--%3E%7C%22%E7%BC%BA%E5%A4%B1%22%7C%20WALK%5B%22%E6%9F%A5%E9%A1%B5%E8%A1%A8%E5%A1%AB%20TLB%22%5D%0A%20%20WALK%20--%3E%20PF%5B%22%E9%A1%B9%E6%97%A0%E6%95%88%EF%BC%9A%E7%BC%BA%E9%A1%B5%22%5D%0A%20%20WALK%20--%3E%20FILL%5B%22%E9%A1%B9%E6%9C%89%E6%95%88%EF%BC%9A%E5%A1%AB%E5%85%A5%E5%86%8D%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>进程切换要换地址空间：刷 TLB，或用 ASID 避免全刷。本课承认必须处理，不把 ASID 编码写完。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TLB 命中率极高时，翻译不出现在 CPI 里。TLB 缺失代价是若干次页表访存，仍远小于缺页的磁盘。权限位在 TLB 里检查，与页表一致；内核改页表后必须作废对应 TLB 项，否则保护被绕过。</p><p>多层 cache 与 TLB 的顺序（先译后查物理 cache，或虚拟 cache 再别名）是实现细节。本课要求：最终数据必须对应正确的物理页，且权限已被检查。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入多级页表走访的硬件状态机——单级表走一次即可。64 位下表太大，下一课才切级。也不把 TLB 缺失算进 cache 的三类缺失；它是翻译停顿，另加进 CPI。</p><p>后课默认：每条访存先看 TLB；命中则翻译对软件不可见。改页表的特权代码负责作废条目。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TLB 缓存 VPN→PPN；命中让翻译跟上流水线。</li><li>TLB 缺失是走页表，不一定缺页。</li><li>多级页表是为了表本身的空间，下一课才切。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V TLB；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const C=n(A,[["render",p]]);export{_ as __pageData,C as default};
